const { LAYOUT_16x9 } = require("../lib/constants");

function createSlide(pres, theme) {
  const slide = pres.addSlide({ layout: LAYOUT_16x9, background: { color: theme.bg } });

  // Decorative shape - large circle (top right)
  slide.addShape(pres.ShapeType.circle, {
    x: 7.5,
    y: -1.5,
    w: 4,
    h: 4,
    fill: { color: theme.secondary, transparency: 15 },
    line: { color: theme.secondary, width: 0 }
  });

  // Decorative shape - medium circle (bottom left)
  slide.addShape(pres.ShapeType.circle, {
    x: -1,
    y: 4,
    w: 3,
    h: 3,
    fill: { color: theme.accent, transparency: 20 },
    line: { color: theme.accent, width: 0 }
  });

  // Decorative shape - small accent circle
  slide.addShape(pres.ShapeType.circle, {
    x: 8.5,
    y: 4.5,
    w: 1.2,
    h: 1.2,
    fill: { color: theme.light, transparency: 25 },
    line: { color: theme.light, width: 0 }
  });

  // Decorative rounded rectangle (top left accent)
  slide.addShape(pres.ShapeType.roundRect, {
    x: 0.5,
    y: 0.4,
    w: 0.15,
    h: 0.8,
    fill: { color: theme.secondary },
    line: { color: theme.secondary, width: 0 },
    rectRadius: 0.08
  });

