function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Decorative shape - large circle (top right)
  slide.addShape(pres.shapes.OVAL, {
    x: 7.5,
    y: -1.5,
    w: 4,
    h: 4,
    fill: { color: theme.secondary, transparency: 15 },
    line: { color: theme.secondary, width: 0 }
  });

  // Decorative shape - medium circle (bottom left)
  slide.addShape(pres.shapes.OVAL, {
    x: -1,
    y: 4,
    w: 3,
    h: 3,
    fill: { color: theme.accent, transparency: 20 },
    line: { color: theme.accent, width: 0 }
  });

  // Decorative shape - small accent circle
  slide.addShape(pres.shapes.OVAL, {
    x: 8.5,
    y: 4.5,
    w: 1.2,
    h: 1.2,
    fill: { color: theme.light, transparency: 25 },
    line: { color: theme.light, width: 0 }
  });

  // Decorative rounded rectangle (top left accent)
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 0.5,
    y: 0.4,
    w: 0.15,
    h: 0.8,
    fill: { color: theme.secondary },
    line: { color: theme.secondary, width: 0 },
    rectRadius: 0.08
  });

  // Decorative rounded rectangle (vertical bar)
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 0.75,
    y: 0.4,
    w: 0.15,
    h: 0.8,
    fill: { color: theme.accent },
    line: { color: theme.accent, width: 0 },
    rectRadius: 0.08
  });

  // Main title
  slide.addText("2024 JavaScript Rising Stars", {
    x: 0.5,
    y: 1.8,
    w: 9,
    h: 1.2,
    fontSize: 48,
    fontFace: "Arial",
    color: theme.primary,
    bold: true,
    align: "left",
    valign: "middle"
  });

  // Subtitle
  slide.addText("The Year's Hottest Projects by GitHub Stars", {
    x: 0.5,
    y: 3.0,
    w: 9,
    h: 0.6,
    fontSize: 22,
    fontFace: "Arial",
    color: theme.secondary,
    align: "left",
    valign: "middle"
  });

  // Meta info
  slide.addText("9th Edition  |  Best of JS Curated  |  stars added in 2024", {
    x: 0.5,
    y: 3.7,
    w: 9,
    h: 0.4,
    fontSize: 14,
    fontFace: "Arial",
    color: theme.primary,
    align: "left",
    valign: "middle"
  });

  // Decorative horizontal line
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 0.5,
    y: 4.3,
    w: 2.5,
    h: 0.06,
    fill: { color: theme.accent },
    line: { color: theme.accent, width: 0 },
    rectRadius: 0.1
  });

  return slide;
}

module.exports = { createSlide };

