// slide-04.js
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 4,
  title: 'htmx Overtakes React as #1 Front-end Framework by Stars Added'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText(slideConfig.title, {
    x: 0.4, y: 0.3, w: 9.2, h: 0.6,
    fontSize: 28, fontFace: "Arial",
    color: theme.primary, bold: true,
    margin: 0
  });

  // Subtitle line
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.4, y: 0.9, w: 1.2, h: 0.05,
    fill: { color: theme.accent }
  });

  // Chart data
  const chartData = [{
    name: "Stars Added",
    labels: ["htmx", "React", "Svelte", "Vue.js", "Angular"],
    values: [16.8, 14.2, 6.1, 5.9, 3.5]
  }];

  // Bar chart - htmx highlighted with accent color, others in secondary
  // PptxGenJS applies chartColors in order to data points
  slide.addChart(pres.charts.BAR, chartData, {
    x: 0.4, y: 1.15, w: 5.5, h: 3.8,
    barDir: "col",
    barGapWidthPct: 50,
    chartColors: [theme.accent, theme.secondary, theme.secondary, theme.secondary, theme.secondary],
    chartArea: { fill: { color: theme.bg }, roundedCorners: true },
    showTitle: false,
    showLegend: false,
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: theme.primary,
    dataLabelFontSize: 11,
    dataLabelFontFace: "Arial",
    catAxisLabelColor: theme.primary,
    catAxisLabelFontSize: 11,
    catAxisLabelFontFace: "Arial",
    valAxisLabelColor: theme.secondary,
    valAxisLabelFontSize: 10,
    valAxisLabelFontFace: "Arial",
    valGridLine: { color: "E8E8E8", size: 0.5 },
    catGridLine: { style: "none" },
    valAxisMaxVal: 20,
    valAxisTitle: "Stars Added (k)",
    valAxisTitleColor: theme.secondary,
    valAxisTitleFontSize: 10,
    valAxisTitleFontFace: "Arial"
  });

  // Key narrative card background
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 6.1, y: 1.15, w: 3.5, h: 3.8,
    fill: { color: "F8F9FA" },
    rectRadius: 0.08
  });

  // Key narrative title
  slide.addText("Key Insights", {
    x: 6.3, y: 1.35, w: 3.1, h: 0.35,
    fontSize: 14, fontFace: "Arial",
    color: theme.primary, bold: true,
    margin: 0
  });

  // Narrative point 1
  slide.addShape(pres.shapes.OVAL, {
    x: 6.3, y: 1.85, w: 0.12, h: 0.12,
    fill: { color: theme.accent }
  });
  slide.addText("htmx extends HTML with hx-* attributes for AJAX, WebSockets without writing JS", {
    x: 6.55, y: 1.75, w: 2.95, h: 0.7,
    fontSize: 11, fontFace: "Arial",
    color: theme.primary, bold: false,
    valign: "top",
    margin: 0
  });

  // Narrative point 2
  slide.addShape(pres.shapes.OVAL, {
    x: 6.3, y: 2.6, w: 0.12, h: 0.12,
    fill: { color: theme.secondary }
  });
  slide.addText("React 19 launched December 2024 with Server Components, Server Functions", {
    x: 6.55, y: 2.5, w: 2.95, h: 0.7,
    fontSize: 11, fontFace: "Arial",
    color: theme.primary, bold: false,
    valign: "top",
    margin: 0
  });

  // Narrative point 3
  slide.addShape(pres.shapes.OVAL, {
    x: 6.3, y: 3.35, w: 0.12, h: 0.12,
    fill: { color: theme.light }
  });
  slide.addText("React evolving from library to \"specification for frameworks\" (Robin Wieruch)", {
    x: 6.55, y: 3.25, w: 2.95, h: 0.7,
    fontSize: 11, fontFace: "Arial",
    color: theme.primary, bold: false,
    valign: "top",
    margin: 0
  });

  // Source note
  slide.addText("Source: GitHub star growth 2024", {
    x: 0.4, y: 5.0, w: 4, h: 0.3,
    fontSize: 9, fontFace: "Arial",
    color: theme.secondary, bold: false,
    margin: 0
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("4", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

// Standalone preview
if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = {
    primary: "264653",
    secondary: "2a9d8f",
    accent: "e9c46a",
    light: "f4a261",
    bg: "FFFFFF"
  };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-04-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

