function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("shadcn/ui: Back-to-Back Champion", {
    x: 0.4, y: 0.3, w: 9.2, h: 0.6,
    fontSize: 28, fontFace: "Arial",
    color: theme.primary, bold: true,
    margin: 0
  });

  // Accent underline
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.4, y: 0.9, w: 1.2, h: 0.05,
    fill: { color: theme.accent }
  });

  // Large stat callout - +38k stars
  slide.addText("+38k", {
    x: 0.4, y: 1.2, w: 2.5, h: 1.2,
    fontSize: 72, fontFace: "Arial",
    color: theme.accent, bold: true,
    align: "left", valign: "middle",
    margin: 0
  });
  slide.addText("stars in 2024", {
    x: 0.4, y: 2.3, w: 2.5, h: 0.4,
    fontSize: 14, fontFace: "Arial",
    color: theme.secondary, bold: false,
    margin: 0
  });

  // Total stars callout
  slide.addText("77.5k", {
    x: 0.4, y: 2.8, w: 2.5, h: 0.6,
    fontSize: 36, fontFace: "Arial",
    color: theme.primary, bold: true,
    margin: 0
  });
  slide.addText("total stars (since Jan 2023)", {
    x: 0.4, y: 3.35, w: 2.5, h: 0.3,
    fontSize: 11, fontFace: "Arial",
    color: theme.secondary, bold: false,
    margin: 0
  });

  // Year-over-year growth card
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 3.2, y: 1.2, w: 2.4, h: 1.8,
    fill: { color: "F8F9FA" },
    rectRadius: 0.08
  });
  slide.addText("Year-over-Year Growth", {
    x: 3.4, y: 1.35, w: 2, h: 0.3,
    fontSize: 11, fontFace: "Arial",
    color: theme.secondary, bold: true,
    margin: 0
  });
  slide.addText("2023: +39.5k", {
    x: 3.4, y: 1.75, w: 2, h: 0.4,
    fontSize: 18, fontFace: "Arial",
    color: theme.primary, bold: true,
    margin: 0
  });
  slide.addText("2024: +38.0k", {
    x: 3.4, y: 2.2, w: 2, h: 0.4,
    fontSize: 18, fontFace: "Arial",
    color: theme.accent, bold: true,
    margin: 0
  });
  slide.addText("Sustained momentum", {
    x: 3.4, y: 2.6, w: 2, h: 0.3,
    fontSize: 10, fontFace: "Arial",
    color: theme.secondary, bold: false,
    margin: 0
  });

  // 2024 highlights card
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 5.8, y: 1.2, w: 3.8, h: 3.6,
    fill: { color: "F8F9FA" },
    rectRadius: 0.08
  });
  slide.addText("2024 Highlights", {
    x: 6.0, y: 1.35, w: 3.4, h: 0.3,
    fontSize: 12, fontFace: "Arial",
    color: theme.primary, bold: true,
    margin: 0
  });

  // Highlight items
  const highlights = [
    "Charts (powered by Recharts)",
    "Themes (CSS variable generation)",
    "Blocks (layout collections)",
    "New responsive sidebar component",
    "CLI: Next.js, Remix, Vite, Laravel, monorepos",
    "Vercel v0 integration for AI-generated components"
  ];

  highlights.forEach((text, i) => {
    slide.addShape(pres.shapes.OVAL, {
      x: 6.0, y: 1.85 + (i * 0.45), w: 0.1, h: 0.1,
      fill: { color: theme.accent }
    });
    slide.addText(text, {
      x: 6.25, y: 1.75 + (i * 0.45), w: 3.2, h: 0.4,
      fontSize: 11, fontFace: "Arial",
      color: theme.primary, bold: false,
      margin: 0
    });
  });

  // Source note
  slide.addText("Source: risingstars.js.org/2024", {
    x: 0.4, y: 5.0, w: 4, h: 0.3,
    fontSize: 9, fontFace: "Arial",
    color: theme.secondary, bold: false,
    margin: 0
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("3", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

module.exports = { createSlide };

